"use client"

/** @responsibility Provides the compatibility entrypoint for the complete Sidebar system. */

export * from "./sidebar/index"

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

const DEFAULT_SIDEBAR_WIDTH = "17rem"
const DEFAULT_SIDEBAR_COLLAPSED_WIDTH = "3.5rem"
const SIDEBAR_MOBILE_BREAKPOINT = "(max-width: 47.999rem)"

/** @responsibility Coordinates shared Sidebar state, shell sizing, focus, and optional commands. */

type SidebarState = "expanded" | "collapsed"
/** Primary modifier choices supported by an exact Sidebar keyboard shortcut. */
type SidebarShortcutModifier = "control" | "meta" | "mod"

/** Describes one exact, opt-in global keyboard shortcut for toggling a Sidebar. */
interface SidebarKeyboardShortcut {
  /**
   * KeyboardEvent key matched without case sensitivity. When `altKey` is
   * required, single letters and digits also match by physical key so Alt
   * combinations work on platforms that remap the produced character.
   */
  key: string
  /**
   * Primary modifier. `mod` accepts exactly one of Meta or Control; omit for
   * neither. Shortcuts without a primary modifier are ignored while the user
   * types in an editable element so plain keystrokes are never swallowed.
   * @defaultValue undefined
   */
  modifier?: SidebarShortcutModifier
  /**
   * Whether Alt must be pressed. Omitted values require Alt not to be pressed.
   * @defaultValue false
   */
  altKey?: boolean
  /**
   * Whether Shift must be pressed. Omitted values require Shift not to be pressed.
   * @defaultValue false
   */
  shiftKey?: boolean
  /**
   * Prevents the matched browser event by default. Set false to preserve it.
   * @defaultValue true
   */
  preventDefault?: boolean
}

/**
 * Determines whether a keyboard event exactly matches a requested primary modifier.
 *
 * @param event - The keyboard event being evaluated.
 * @param modifier - The required primary modifier, or undefined when neither is allowed.
 * @returns Whether the event's Control and Meta keys satisfy the requested modifier.
 */
function matchesShortcutModifier(
  event: KeyboardEvent,
  modifier: SidebarShortcutModifier | undefined,
) {
  switch (modifier) {
    case "mod":
      return event.metaKey !== event.ctrlKey
    case "meta":
      return event.metaKey && !event.ctrlKey
    case "control":
      return event.ctrlKey && !event.metaKey
    case undefined:
      return !event.metaKey && !event.ctrlKey
    default: {
      const exhaustiveModifier: never = modifier
      return exhaustiveModifier
    }
  }
}

/** Keyboard events already claimed by one provider's shortcut handler. */
const handledShortcutEvents = new WeakSet<KeyboardEvent>()

/**
 * Determines whether a keyboard event originates from a text-editing element.
 *
 * @param event - The keyboard event being evaluated.
 * @returns Whether the event target consumes plain keystrokes for editing.
 */
function isEditableShortcutTarget(event: KeyboardEvent) {
  const target = event.target

  if (!(target instanceof HTMLElement)) return false

  return (
    target.isContentEditable ||
    target instanceof HTMLInputElement ||
    target instanceof HTMLTextAreaElement ||
    target instanceof HTMLSelectElement
  )
}

/**
 * Determines whether a keyboard event matches the configured shortcut key.
 *
 * @param event - The keyboard event being evaluated.
 * @param key - The configured shortcut key, matched without case sensitivity.
 * @param altKeyRequired - Whether the shortcut requires Alt, enabling physical-key matching.
 * @returns Whether the event's produced or physical key satisfies the shortcut key.
 */
function matchesShortcutKey(event: KeyboardEvent, key: string, altKeyRequired: boolean) {
  const normalizedKey = key.toLowerCase()

  if (event.key.toLowerCase() === normalizedKey) return true
  if (!altKeyRequired || !/^[a-z0-9]$/.test(normalizedKey)) return false

  const physicalCode = /^[0-9]$/.test(normalizedKey)
    ? `digit${normalizedKey}`
    : `key${normalizedKey}`

  return event.code.toLowerCase() === physicalCode
}

/** State and controls returned by `useSidebar`. */
interface SidebarContextValue {
  /** Semantic presentation derived from the current visibility. */
  state: SidebarState
  /** Whether the coordinated Sidebar is currently open. */
  open: boolean
  /** Updates Sidebar visibility from a value or state updater. */
  setOpen: React.Dispatch<React.SetStateAction<boolean>>
  /** Reverses the current Sidebar visibility. */
  toggleSidebar: () => void
  /** Wrapper used as the portal boundary for mobile Sidebar content. */
  portalContainerRef: React.RefObject<HTMLDivElement | null>
  /** Most recent trigger used for mobile focus restoration. */
  lastTriggerRef: React.RefObject<HTMLElement | null>
}

const SidebarContext = React.createContext<SidebarContextValue | null>(null)

/**
 * Subscribes to changes of the Sidebar's mobile media query.
 *
 * @param onChange - Called whenever the media-query match state changes.
 * @returns A cleanup function that removes the subscription.
 */
function subscribeToMobileViewport(onChange: () => void) {
  const mediaQuery = window.matchMedia(SIDEBAR_MOBILE_BREAKPOINT)

  mediaQuery.addEventListener("change", onChange)
  return () => mediaQuery.removeEventListener("change", onChange)
}

/**
 * Reads whether the mobile Sidebar media query currently matches.
 *
 * @returns The current mobile media-query match state.
 */
function getIsMobileSnapshot() {
  return window.matchMedia(SIDEBAR_MOBILE_BREAKPOINT).matches
}

/**
 * Provides the server-render value for the mobile media query.
 *
 * @returns False, so server markup always renders the desktop presentation.
 */
function getServerIsMobileSnapshot() {
  return false
}

/**
 * Observes whether the current viewport uses the Sidebar's mobile presentation.
 *
 * @returns Whether the mobile Sidebar media query currently matches.
 */
function useIsMobile() {
  return React.useSyncExternalStore(
    subscribeToMobileViewport,
    getIsMobileSnapshot,
    getServerIsMobileSnapshot,
  )
}

/**
 * Reads the shared state and controls for the nearest Sidebar provider.
 *
 * @returns The current Sidebar state, state controls, and focus-management references.
 * @throws When called outside a SidebarProvider.
 */
function useSidebar() {
  const context = React.useContext(SidebarContext)

  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.")
  }

  return context
}

/** Properties accepted by the shared Sidebar state and layout provider. */
interface SidebarProviderProps extends React.ComponentProps<"div"> {
  /**
   * Width used by icon-collapsed Sidebars.
   * @defaultValue "3.5rem"
   */
  collapsedSidebarWidth?: string
  /**
   * Initial visibility for an uncontrolled provider.
   * @defaultValue true
   */
  defaultOpen?: boolean
  /** Current visibility when the provider is controlled by its consumer. */
  open?: boolean
  /** Called whenever a consumer interaction requests a visibility change. */
  onOpenChange?: (open: boolean) => void
  /**
   * Exact global shortcut for toggling. Omit to disable keyboard toggling.
   * @defaultValue undefined
   */
  keyboardShortcut?: SidebarKeyboardShortcut
  /**
   * Width used by expanded Sidebars.
   * @defaultValue "17rem"
   */
  sidebarWidth?: string
}

/**
 * Provides shared Sidebar state, sizing, focus coordination, and optional keyboard control.
 *
 * @param props - Controlled or uncontrolled state, widths, shortcut configuration, and native wrapper properties.
 * @returns A context provider and shell wrapper for one coordinated Sidebar layout.
 */
function SidebarProvider({
  collapsedSidebarWidth = DEFAULT_SIDEBAR_COLLAPSED_WIDTH,
  defaultOpen = true,
  open: openProp,
  onOpenChange,
  keyboardShortcut,
  sidebarWidth = DEFAULT_SIDEBAR_WIDTH,
  className,
  style,
  children,
  ...props
}: SidebarProviderProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen)
  const portalContainerRef = React.useRef<HTMLDivElement>(null)
  const lastTriggerRef = React.useRef<HTMLElement>(null)
  const open = openProp ?? uncontrolledOpen

  /**
   * Resolves and publishes a controlled or uncontrolled Sidebar visibility update.
   *
   * @param value - The next visibility or a function deriving it from current state.
   * @returns Nothing; provider state and the change callback are updated.
   */
  const setOpen = React.useCallback<React.Dispatch<React.SetStateAction<boolean>>>(
    (value) => {
      const nextOpen = typeof value === "function" ? value(open) : value

      if (openProp === undefined) {
        setUncontrolledOpen(nextOpen)
      }

      onOpenChange?.(nextOpen)
    },
    [onOpenChange, open, openProp],
  )

  /**
   * Reverses the current Sidebar visibility state.
   *
   * @returns Nothing; the provider receives the opposite visibility state.
   */
  const toggleSidebar = React.useCallback(() => {
    setOpen((currentOpen) => !currentOpen)
  }, [setOpen])

  const shortcutKey = keyboardShortcut?.key
  const shortcutModifier = keyboardShortcut?.modifier
  const shortcutAltKey = Boolean(keyboardShortcut?.altKey)
  const shortcutShiftKey = Boolean(keyboardShortcut?.shiftKey)
  const shortcutPreventsDefault = keyboardShortcut?.preventDefault !== false

  React.useEffect(() => {
    if (!shortcutKey) return

    /**
     * Toggles the Sidebar when an event exactly matches the configured shortcut.
     *
     * @param event - The global keyboard event being evaluated.
     * @returns Nothing; a matching event may be prevented and toggle the provider.
     */
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || event.isComposing) return
      if (handledShortcutEvents.has(event)) return
      if (shortcutModifier === undefined && isEditableShortcutTarget(event)) return

      const keyMatches = matchesShortcutKey(event, shortcutKey, shortcutAltKey)
      const modifierMatches = matchesShortcutModifier(event, shortcutModifier)
      const altKeyMatches = event.altKey === shortcutAltKey
      const shiftKeyMatches = event.shiftKey === shortcutShiftKey
      const shortcutMatches =
        keyMatches && modifierMatches && altKeyMatches && shiftKeyMatches

      if (!shortcutMatches) return

      handledShortcutEvents.add(event)
      if (shortcutPreventsDefault) event.preventDefault()
      toggleSidebar()
    }

    window.addEventListener("keydown", handleKeyDown)
    return () => window.removeEventListener("keydown", handleKeyDown)
  }, [
    shortcutAltKey,
    shortcutKey,
    shortcutModifier,
    shortcutPreventsDefault,
    shortcutShiftKey,
    toggleSidebar,
  ])

  const contextValue = React.useMemo<SidebarContextValue>(
    () => ({
      state: open ? "expanded" : "collapsed",
      open,
      setOpen,
      toggleSidebar,
      portalContainerRef,
      lastTriggerRef,
    }),
    [open, setOpen, toggleSidebar],
  )

  return (
    <SidebarContext.Provider value={contextValue}>
      <div
        ref={portalContainerRef}
        data-slot="sidebar-wrapper"
        style={
          {
            "--nessa-sidebar-width": sidebarWidth,
            "--nessa-sidebar-width-icon": collapsedSidebarWidth,
            ...style,
          } as React.CSSProperties
        }
        className={cn(
          "group/sidebar-wrapper flex min-h-svh w-full bg-background font-sans text-foreground",
          "md:has-data-[variant=inset]:bg-sidebar",
          className,
        )}
        {...props}
      >
        {children}
      </div>
    </SidebarContext.Provider>
  )
}

export {
  SidebarProvider,
  useIsMobile,
  useSidebar,
  type SidebarKeyboardShortcut,
  type SidebarProviderProps,
  type SidebarShortcutModifier,
}

"use client"

import * as React from "react"
import { Dialog } from "radix-ui"

import { cn } from "@/lib/utils"

import { useIsMobile, useSidebar } from "./sidebar-provider"
import { SidebarInner } from "./sidebar-inner"
import {
  SidebarCollapsible,
  SidebarSide,
  SidebarVariant,
  type SidebarCollapsible as SidebarCollapsibleType,
  type SidebarSide as SidebarSideType,
  type SidebarVariant as SidebarVariantType,
} from "./sidebar-options"

/** @responsibility Presents the responsive navigation shell from shared Sidebar state. */

/** Properties accepted by the responsive Sidebar shell. */
interface SidebarProps extends React.ComponentProps<"div"> {
  /**
   * Physical edge on which the Sidebar is positioned.
   * @defaultValue SidebarSide.Left
   */
  side?: SidebarSideType
  /**
   * Visual relationship between the Sidebar and adjacent application content.
   * @defaultValue SidebarVariant.Sidebar
   */
  variant?: SidebarVariantType
  /**
   * Behavior used when the shared Sidebar state is collapsed.
   * @defaultValue SidebarCollapsible.Offcanvas
   */
  collapsible?: SidebarCollapsibleType
}

/**
 * Renders a responsive Sidebar shell connected to the nearest Sidebar provider.
 *
 * @param props - Shell placement, presentation, collapse behavior, content, and native div properties.
 * @returns A complementary landmark, or a modal panel while a collapsible mobile Sidebar is open.
 */
function Sidebar({
  side = SidebarSide.Left,
  variant = SidebarVariant.Sidebar,
  collapsible = SidebarCollapsible.Offcanvas,
  className,
  children,
  ...props
}: SidebarProps) {
  const { lastTriggerRef, open, portalContainerRef, setOpen, state } = useSidebar()
  const isMobile = useIsMobile()
  const mobileTriggerRef = React.useRef<HTMLElement | null>(null)
  const isCollapsed = collapsible !== SidebarCollapsible.None && !open
  const isLeft = side === SidebarSide.Left
  const isFloating = variant === SidebarVariant.Floating
  const isInset = variant === SidebarVariant.Inset
  const isIconCollapsible = collapsible === SidebarCollapsible.Icon
  const isOffcanvasCollapsible =
    collapsible === SidebarCollapsible.Offcanvas
  const previousOpenRef = React.useRef(open)

  /**
   * Restores focus to the trigger associated with a closing mobile Sidebar.
   *
   * @returns Nothing; focus is moved when an eligible trigger is available.
   */
  const restoreMobileTrigger = React.useCallback(() => {
    const previousTrigger = lastTriggerRef.current ?? mobileTriggerRef.current
    lastTriggerRef.current = null

    if (previousTrigger?.isConnected) {
      previousTrigger.focus()
      return
    }

    requestAnimationFrame(() => {
      const triggerLabel = previousTrigger?.getAttribute("aria-label")
      const mountedTriggers =
        portalContainerRef.current?.querySelectorAll<HTMLElement>(
          '[data-slot="sidebar-trigger"]',
        )
      const matchingTrigger = Array.from(mountedTriggers ?? []).find(
        (trigger) =>
          !triggerLabel || trigger.getAttribute("aria-label") === triggerLabel,
      )

      matchingTrigger?.focus()
    })
  }, [lastTriggerRef, portalContainerRef])

  React.useEffect(() => {
    const wasOpen = previousOpenRef.current
    previousOpenRef.current = open

    if (isMobile && isIconCollapsible && wasOpen && !open) {
      restoreMobileTrigger()
    }
  }, [isIconCollapsible, isMobile, open, restoreMobileTrigger])

  const panel = (
    <SidebarInner collapsible={collapsible} collapsed={isCollapsed} side={side}>
      {children}
    </SidebarInner>
  )

  if (
    isMobile &&
    collapsible !== SidebarCollapsible.None &&
    (isOffcanvasCollapsible || open)
  ) {
    return (
      <Dialog.Root open={open} onOpenChange={setOpen} modal>
        <Dialog.Portal container={portalContainerRef.current}>
          <Dialog.Overlay className="fixed inset-0 z-40 bg-background/80 backdrop-blur-xs" />
          <Dialog.Content
            data-slot="sidebar"
            data-state={state}
            data-collapsible={isCollapsed ? collapsible : ""}
            data-variant={variant}
            data-side={side}
            aria-describedby={undefined}
            onOpenAutoFocus={() => {
              mobileTriggerRef.current =
                lastTriggerRef.current ??
                (document.activeElement as HTMLElement | null)
            }}
            onCloseAutoFocus={(event) => {
              event.preventDefault()
              restoreMobileTrigger()
            }}
            className={cn(
              "group/sidebar fixed inset-y-0 z-50 flex w-[min(var(--nessa-sidebar-width),calc(100vw-3rem))] flex-col overflow-hidden border-sidebar-border bg-sidebar text-sidebar-foreground shadow-lg outline-none",
              isLeft ? "left-0 border-r" : "right-0 border-l",
              (isFloating || isInset) &&
                "m-2 h-[calc(100svh-1rem)] rounded-xl border",
              className,
            )}
            {...props}
          >
            <Dialog.Title className="sr-only">
              {props["aria-label"] ?? "Application navigation"}
            </Dialog.Title>
            {panel}
          </Dialog.Content>
        </Dialog.Portal>
      </Dialog.Root>
    )
  }

  return (
    <div
      role="complementary"
      data-slot="sidebar"
      data-state={collapsible === SidebarCollapsible.None ? "expanded" : state}
      data-collapsible={isCollapsed ? collapsible : ""}
      data-variant={variant}
      data-side={side}
      className={cn(
        "group/sidebar peer relative flex h-svh shrink-0 flex-col overflow-hidden bg-sidebar text-sidebar-foreground transition-[width,transform,border-color,padding] duration-200 ease-linear max-md:fixed max-md:inset-y-0 max-md:z-40",
        isLeft
          ? "border-r border-sidebar-border"
          : "border-l border-sidebar-border",
        isLeft ? "max-md:left-0" : "max-md:right-0",
        isFloating &&
          "m-2 h-[calc(100svh-1rem)] rounded-xl border shadow-sm",
        isInset &&
          "md:border-transparent md:bg-transparent",
        !isCollapsed && "w-(--nessa-sidebar-width)",
        isCollapsed &&
          isIconCollapsible &&
          "w-(--nessa-sidebar-width-icon)",
        isCollapsed &&
          isOffcanvasCollapsible &&
          "w-0 border-transparent",
        className,
      )}
      {...props}
    >
      {panel}
    </div>
  )
}

export { Sidebar, type SidebarProps }

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  SidebarCollapsible,
  SidebarSide,
  type SidebarCollapsible as SidebarCollapsibleType,
  type SidebarSide as SidebarSideType,
} from "./sidebar-options"

/** @responsibility Applies the shared visual and visibility behavior to Sidebar contents. */

/** Inputs used by Sidebar to render its shared inner container. */
interface SidebarInnerProps extends React.ComponentProps<"div"> {
  /** Collapse behavior applied by the owning Sidebar. */
  collapsible: SidebarCollapsibleType
  /** Whether the owning Sidebar is currently collapsed. */
  collapsed: boolean
  /** Physical edge on which the owning Sidebar is positioned. */
  side: SidebarSideType
}

/**
 * Renders the shared visual container inside desktop and mobile Sidebars.
 *
 * @param props - Visibility, collapse, side, and native div properties supplied by Sidebar.
 * @returns The styled inner container with the requested collapse presentation.
 */
function SidebarInner({
  collapsible,
  collapsed,
  side,
  className,
  ...props
}: SidebarInnerProps) {
  const isOffcanvasHidden =
    collapsed && collapsible === SidebarCollapsible.Offcanvas
  const isIconCollapsed =
    collapsed && collapsible === SidebarCollapsible.Icon
  const isLeft = side === SidebarSide.Left

  return (
    <div
      data-slot="sidebar-inner"
      aria-hidden={isOffcanvasHidden || undefined}
      inert={isOffcanvasHidden || undefined}
      className={cn(
        "flex h-full min-h-0 w-(--nessa-sidebar-width) flex-col overflow-hidden bg-sidebar transition-transform duration-200 ease-linear",
        isIconCollapsed && "w-(--nessa-sidebar-width-icon)",
        isOffcanvasHidden &&
          (isLeft ? "-translate-x-full" : "translate-x-full"),
        className,
      )}
      {...props}
    />
  )
}

export { SidebarInner, type SidebarInnerProps }

/** @responsibility Defines the stable layout and collapse choices supported by Sidebar. */

/** Physical edges supported by the Sidebar shell. */
const SidebarSide = Object.freeze({
  Left: "left",
  Right: "right",
} as const)

/** A supported physical edge for the Sidebar shell. */
type SidebarSide = (typeof SidebarSide)[keyof typeof SidebarSide]

/** Visual shell presentations supported by Sidebar. */
const SidebarVariant = Object.freeze({
  Sidebar: "sidebar",
  Floating: "floating",
  Inset: "inset",
} as const)

/** A supported visual relationship between Sidebar and application content. */
type SidebarVariant = (typeof SidebarVariant)[keyof typeof SidebarVariant]

/** Collapse behaviors supported by Sidebar. */
const SidebarCollapsible = Object.freeze({
  Offcanvas: "offcanvas",
  Icon: "icon",
  None: "none",
} as const)

/** A supported behavior for presenting a collapsed Sidebar. */
type SidebarCollapsible =
  (typeof SidebarCollapsible)[keyof typeof SidebarCollapsible]

export {
  SidebarCollapsible,
  SidebarSide,
  SidebarVariant,
}

import * as React from "react"

import { cn } from "@/lib/utils"

/** @responsibility Provides the leading region for Sidebar identity and primary controls. */

/**
 * Renders the leading region for Sidebar identity and primary controls.
 *
 * @param props - Native div properties, including children and optional styling overrides.
 * @returns A non-shrinking header container at the start of the Sidebar.
 */
function SidebarHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-header"
      className={cn("flex shrink-0 flex-col gap-2 p-3", className)}
      {...props}
    />
  )
}

export { SidebarHeader }

import * as React from "react"

import { cn } from "@/lib/utils"

/** @responsibility Provides the flexible content region for primary Sidebar navigation. */

/**
 * Renders the scrollable region that contains a Sidebar's primary content.
 *
 * @param props - Native div properties, including children and optional styling overrides.
 * @returns A flexible, vertically scrollable Sidebar content container.
 */
function SidebarContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-content"
      className={cn(
        "flex min-h-0 flex-1 flex-col gap-1 overflow-y-auto overflow-x-hidden overscroll-contain px-2 pb-3",
        className,
      )}
      {...props}
    />
  )
}

export { SidebarContent }

import * as React from "react"

import { cn } from "@/lib/utils"

/** @responsibility Provides the terminal region for persistent Sidebar actions or identity. */

/**
 * Renders the terminal region for persistent Sidebar content.
 *
 * @param props - Native div properties, including children and optional styling overrides.
 * @returns A footer container anchored after the Sidebar's flexible content.
 */
function SidebarFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-footer"
      className={cn(
        "mt-auto flex shrink-0 flex-col gap-1 border-t border-sidebar-border p-2",
        className,
      )}
      {...props}
    />
  )
}

export { SidebarFooter }

import * as React from "react"

import { cn } from "@/lib/utils"

/** @responsibility Provides the primary workspace region adjacent to a Sidebar. */

/**
 * Renders the primary application workspace adjacent to a Sidebar.
 *
 * When the sibling Sidebar uses the inset variant, the workspace floats as a
 * rounded panel beside the flush Sidebar surface.
 *
 * @param props - Native main properties, including children and optional styling overrides.
 * @returns A flexible main landmark that fills the remaining shell width.
 */
function SidebarInset({ className, ...props }: React.ComponentProps<"main">) {
  return (
    <main
      data-slot="sidebar-inset"
      className={cn(
        "relative flex min-w-0 flex-1 flex-col bg-background",
        "md:peer-data-[variant=inset]:m-2 md:peer-data-[variant=inset]:rounded-xl md:peer-data-[variant=inset]:shadow-sm",
        "md:peer-data-[variant=inset]:peer-data-[side=left]:ml-0 md:peer-data-[variant=inset]:peer-data-[side=right]:mr-0",
        className,
      )}
      {...props}
    />
  )
}

export { SidebarInset }

import * as React from "react"
import { Slot } from "radix-ui"

import { cn } from "@/lib/utils"

/** @responsibility Organizes related Sidebar content under an optional label and action. */

/**
 * Renders a semantic section for related Sidebar content.
 *
 * @param props - Native section properties, including the group's children and styling overrides.
 * @returns A positioned Sidebar section that can coordinate its label, action, and content.
 */
function SidebarGroup({ className, ...props }: React.ComponentProps<"section">) {
  return (
    <section
      data-slot="sidebar-group"
      className={cn("relative flex w-full min-w-0 flex-col py-2", className)}
      {...props}
    />
  )
}

/**
 * Renders the accessible heading for a Sidebar group.
 *
 * @param props - Native heading properties, including label content and styling overrides.
 * @returns A level-two heading that follows the Sidebar's collapsed-state presentation.
 */
function SidebarGroupLabel({ className, ...props }: React.ComponentProps<"h2">) {
  return (
    <h2
      data-slot="sidebar-group-label"
      className={cn(
        "flex min-h-8 shrink-0 items-center px-2.5 text-xs font-medium text-sidebar-foreground/60 transition-[height,margin,opacity] duration-200 group-data-[state=collapsed]/sidebar:-mt-8 group-data-[state=collapsed]/sidebar:opacity-0",
        className,
      )}
      {...props}
    />
  )
}

/** Properties accepted by the optional action associated with a Sidebar group. */
interface SidebarGroupActionProps extends React.ComponentProps<"button"> {
  /**
   * Merges behavior and styling into the single child element instead of rendering a button.
   * @defaultValue false
   */
  asChild?: boolean
}

/**
 * Renders an optional action associated with a Sidebar group.
 *
 * @param props - Button properties and optional child-composition behavior.
 * @returns A group-aligned action control, or the supplied child when `asChild` is enabled.
 */
function SidebarGroupAction({
  asChild = false,
  className,
  ...props
}: SidebarGroupActionProps) {
  const Comp = asChild ? Slot.Root : "button"

  return (
    <Comp
      type={asChild ? undefined : "button"}
      data-slot="sidebar-group-action"
      data-sidebar="group-action"
      className={cn(
        "absolute end-2 top-2.5 inline-flex size-7 items-center justify-center rounded-md border-0 bg-transparent p-0 text-sidebar-foreground/60 outline-none transition-colors hover:bg-sidebar-accent hover:text-sidebar-accent-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sidebar-ring group-data-[state=collapsed]/sidebar:hidden [&>svg]:size-4 [&>svg]:shrink-0",
